-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.billing_nudge(p_phone text)
 RETURNS TABLE(nudge text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare v_n int; v_atid text; v_status text; v_last timestamptz;
begin
  select case when digest.resolve_asker(p_phone) is not null then 1 else 0 end into v_n;
  if v_n <> 1 then return; end if;
  select digest.resolve_asker(p_phone) into v_atid;
  if v_atid is null then return; end if;

  select lower(coalesce(digest.attr_clean(mp.at_fields->>'Stripe Subscription Status'), ''))
    into v_status from digest.member_profiles mp where mp.at_member_id = v_atid limit 1;
  if v_status not in ('past_due', 'unpaid') then return; end if;

  select n.last_nudged_at into v_last from digest.olivia_billing_nudges n where n.at_member_id = v_atid;
  if v_last is not null and v_last > now() - interval '24 hours' then return; end if;

  insert into digest.olivia_billing_nudges as n (at_member_id, last_nudged_at)
  values (v_atid, now())
  on conflict (at_member_id) do update set last_nudged_at = now();

  return query select
    ('💳 One more thing — a payment on your membership did not go through. Everything still works; you can update your card in two minutes here: https://checkout.mds.co/p/login/8wM5l70XvaBC6Ji000 — or reply YES and I will connect you with the team.')::text;
end $function$
